    sr=[r for r in range(h) if np.all(A[r]==sepv)][0]
    sc=[c for c in range(w) if np.all(A[:,c]==sepv)][0]
    H=h-1; W=w-1
    out=[[int(bg)]*W for _ in range(H)]
    for r,c in sorted(S):
        rr=r if r<sr else r-1; cc=c if c<sc else c-1
        for a in (rr,H-1-rr):
            for b in (cc,W-1-cc):
                out[a][b]=int(sepv)
    return out
